import{_ as r,o as i,c as t,a3 as a,j as e,a as s}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/suchen-gruppenprozesse/schueler-schuelercontainer.png",u="/bilder/suchen-gruppenprozesse/schueler-schuelercontainer-auswahlmenu.png",h="/bilder/suchen-gruppenprozesse/schueler-schuelercontainer-rechte-maustaste.png",d="/bilder/suchen-gruppenprozesse/schueler-schuelercontainer-mailadressen.png",k=JSON.parse('{"title":"Die Schülerauswahl im Container verwenden","description":"","frontmatter":{"title":"Die Schülerauswahl im Container verwenden","source_pageid":231,"source_revision":5084},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/schuelercontainer-schueler.md","filePath":"schild3/suchen-gruppenprozesse/schuelercontainer-schueler.md"}'),c={name:"schild3/suchen-gruppenprozesse/schuelercontainer-schueler.md"};function o(g,n,p,m,b,w){return i(),t("div",null,[...n[0]||(n[0]=[a('<h1 id="die-schulerauswahl-im-container-verwenden" tabindex="-1">Die Schülerauswahl im Container verwenden <a class="header-anchor" href="#die-schulerauswahl-im-container-verwenden" aria-label="Permalink to &quot;Die Schülerauswahl im Container verwenden&quot;">​</a></h1><p>Der Schülercontainer ist der Ausgangspunkt für die Auswahl von Datensätzen. Hier lernen Sie die Auswahlmöglichkeiten kennen; das ergänzende Video zeigt die Bedienung im Zusammenhang.</p><h2 id="schuler-auswahlen-und-auswahl-eingrenzen" tabindex="-1">Schüler auswählen und Auswahl eingrenzen <a class="header-anchor" href="#schuler-auswahlen-und-auswahl-eingrenzen" aria-label="Permalink to &quot;Schüler auswählen und Auswahl eingrenzen&quot;">​</a></h2><p>Wählen Sie die Schülerinnen und Schüler aus, mit denen Sie arbeiten möchten. Der Container zeigt die aktuelle Auswahl und stellt Schnellfilter nach Status, Klasse, Kurs und weiteren Merkmalen bereit.</p><p><a href="/bilder/suchen-gruppenprozesse/schueler-schuelercontainer.png"><img src="'+l+'" alt="Hauptseite im Reiter Schüler" loading="lazy"></a></p><p><em>Hauptseite im Reiter Schüler</em></p><p>Auf der linken Seite des Hauptfensters befindet sich der Schüler-Container. Hier wird die aktuell ausgewählte Schülergruppe gezeigt.</p><p>Beim Programmstart werden zunächst alle aktiven Schüler der Schule aufgelistet. Diese sogenannte Standard-Auswahl wird durch ein grünes Filtersymbol signalisiert.</p><p>Durch Anklicken eines einzelnen Datensatzes werden die zugehörigen Daten auf den Karteireitern gezeigt.</p><p>Die Anzahl der zur Zeit gefilterten Datensätze wird unten links in der Ecke angezeigt.</p><p><a href="/bilder/suchen-gruppenprozesse/schueler-schuelercontainer-auswahlmenu.png"><img src="'+u+'" alt="Aktuelle Schülerauswahl" loading="lazy"></a></p><p><em>Aktuelle Schülerauswahl</em></p><p>Oberhalb des Containers befindet sich ein Auswahlfeld, um schnell und unkompliziert bestimmte Schülermengen auszuwählen. Durch Mausklick auf das Dreieck öffnet sich das Auswahlmenu.</p><p>Hier kann Status, Klasse, Kurs, Jahrgang und/oder Abteilung der Schüler aktiviert werden.</p><p>Beim Berufskolleg kann zusätzlich die Fachklasse und die Gliederung gefiltert werden.</p><p>Die abgebildete Einstellung zeigt alle aktiven Schülerinnen und Schüler der Klassen 5b und 5c im Schülercontainer. Für diese Auswahl können Sie zum Beispiel einen Elternbrief drucken oder einen Gruppenprozess ausführen, etwa um allen das Fach Informatik zuzuweisen.</p><p>Das gelbe Filtersymbol verdeutlicht, dass aktuell ein Schnellfilter aktiviert ist. Die entsprechende Einstellung kann dort abgelesen werden.</p><p>Zur vollständigen Standardauswahl kehren Sie mit <strong>Standard-Auswahl</strong> im Menüband zurück. Alternativ doppelklicken Sie auf das gelbe Filtersymbol.</p><p><a href="/bilder/suchen-gruppenprozesse/schueler-schuelercontainer-rechte-maustaste.png"><img src="'+h+'" alt="Betätigung der rechten Maustaste im Schülercontainer" loading="lazy"></a></p><p><em>Betätigung der rechten Maustaste im Schülercontainer</em></p><p>Neben der Funktion, die Menge der Schüler zur Weiterverarbeitung und zum Druck zu steuern, können im Container noch einige andere Funktionen ausgeführt werden.</p><p>Diese zeigen sich bei einem Klick mit der rechten Maustaste in den Containerbereich. (siehe Bild)</p><p>Informationen zu Farben anzeigen<br> Manchmal werden Schülernamen in einer anderen Farbe dargestellt. Durch Auswahl von &quot;Informationen zu Farben anzeigen&quot; erscheint eine Legende zu den verschiedenen Farben.</p><p>Alle Auswählen<br> Die Funktion setzt bei allen angezeigten Schülerinnen und Schülern ein Markierungshäkchen. Entfernen Sie bei Bedarf einzelne Häkchen. Mit <strong>Filter auf markierte Schüler</strong> zeigen Sie anschließend nur die markierten Personen an.</p><p>Die Markierungen bleiben erhalten, bis Sie sie aufheben. Sind beim Schließen von SchILD-NRW 3 noch Personen markiert, fragt das Programm, ob die Markierungen für die nächste Sitzung gespeichert werden sollen.</p><p>Komplement zur Auswahl<br> Bei allen Schülern aus dem Schülercontainer wird das Markierungshäkchen geändert.</p><p>Auswahl aufheben<br> Alle Markierungshäkchen werden aufgehoben.</p><p>Ausgewählte Namen in Zwischenablage kopieren<br> Ausgewählte Namen werden im Zwischenspeicher kopiert und können beispielsweise mittels &quot;einfügen&quot; in ein anderes Dokument kopiert werden.</p><p>Auswahl in Excel-Datei<br> Es öffnet sich ein Vorschau-Fenster. Durch Bestätigen über den &quot;Speichern&quot;-Button werden die Spalten in einer Excel-Datei gespeichert.<br><strong>Weitere Spalten anzeigen:</strong> Aktivieren Sie unter <strong>Verwaltung → Globale Einstellungen</strong> die Option <strong>Individuelle Gestaltung der Schüler-Übersichtstabelle ermöglichen</strong>. Anschließend können Sie in den individuellen Einstellungen weitere Spalten ergänzen, etwa Geburtsdatum oder Telefonnummer.</p><p>E-Mail an ausgewählte Schüler senden<br> Je nach Einstellung, ob Mails über das Standard-Mailprogramm oder über den SMTP-Server geschickt werden sollen, öffnet sich das Standard-Mailprogramm oder eine Fenster zum Versenden der E-Mail. Unter Verwaltung ➜ Einstellungen kann angegeben werden, ob die private oder schulische Mailadresse bevorzugt werden soll.</p><p>E-Mail an Erzieher des ausgewählten Schülers senden<br> Alle Erziehungsberechtigten, bei denen die Option &quot;erhält Anschreiben&quot; aktiviert ist, erhalten eine Mail. Analog zur Schülermail öffnet sich vorab das Standard-Mailprogramm oder ein Vorschau-Fenster.</p><p><a href="/bilder/suchen-gruppenprozesse/schueler-schuelercontainer-mailadressen.png"><img src="'+d+'" alt="Weitere Adressen" loading="lazy"></a></p><p><em>Weitere Adressen</em></p><p>E-Mail weitere Adressen der ausgewählten Schülers senden<br> Mit dieser Option kann eine Mail an einen Betrieb senden, der unter weiteren Adressen bei einem Schüler eingetragen ist.</p><p>E-Mail an Betreuer der ausgewählten SchülerInnen senden<br> Mit dieser Funktion senden Sie eine E-Mail an die bei den <strong>weiteren Adressen</strong> hinterlegte Ansprechperson. Über die Schaltfläche <strong>i</strong> (Information) können Sie deren E-Mail-Adresse anzeigen.</p><p>E-Mail an alle Lehrkräfte des ausgewählten Schülers senden<br> Zum Versenden einer Mail an alle Lehrkräfte, die im aktuellen Halbjahr bei den Fächern der Schüler hinterlegt sind. Unter Verwaltung ➜ Einstellungen kann angegeben werden, ob die private oder schulische Mailadresse bevorzugt werden soll.</p><p>Zu individueller Schülergruppe hinzufügen<br> Mit dieser Option können SchülerInnen einer individuellen Schülergruppe hinzugefügt werden. Es öffnet sich ein Fenster, in dem die Schülergruppe, in der die jeweiligen Schüler hinzugefügt werden sollen, ausgewählt werden kann. Durch das Markierungshäkchen können auch mehrere Schüler gleichzeitig einer Schülergruppe hinzugefügt werden.</p><p>Zu allgemeiner Personengruppe hinzufügen<br> Mit dieser Option können ein oder mehrere SchülerInnen einer allgemeinen Personengruppe hinzugefügt werden. Es öffnet sich ein Fenster, um die entsprechende Personengruppe auszuwählen.</p><p>Basisdaten in Vorlage übernehmen<br> Diese Funktion bewirkt, dass beim aktuell ausgewählten Schüler einige Basisdaten (Wohnort, Aufnahmedatum, ...) in eine Vorlage kopiert werden. Sollte danach ein Schülerdatensatz durch &quot;<strong>+</strong>&quot; hinzugefügt werden, so werden diese Basisdaten bei dem neu erzeugten Schüler-Datensatz bereits vorausgefüllt.</p><p>Basisdaten aus Vorlage löschen<br> Löscht die Vorgaben aus der vorangegangenen Funktion.</p><p>Informationelle Selbstauskunft für Schüler erstellen<br> Mit Hilfe dieser Option kann eine CSV-Datei erstellt werden, in der sämtliche Informationen des ausgewählten Schülers enthalten sind.</p><p>Schüler duplizieren<br> Nach Auswahl der Funktion fragt SchILD-NRW 3, ob der neue Datensatz als Duplikat gekennzeichnet werden soll.</p><ul><li><strong>Ja:</strong> Der neue Datensatz erhält den Status <strong>Neuaufnahme</strong>. Unter <strong>Individualdaten I</strong> ist <strong>Ist Duplikat</strong> gesetzt; die Namensliste zeigt den Eintrag gelb. Eine Klasse ist noch nicht zugeordnet.</li><li><strong>Nein:</strong> Der neue Datensatz wird ohne Duplikatkennzeichnung angelegt.</li></ul><p>Schüler sperren<br> Durch diese Option können Schüler gesperrt werden. Die Bearbeitung ist für diese Schüler nicht möglich.</p><p>Sperrung aufheben<br> Mit dieser Option kann die Sperrung aufgehoben werden.</p><hr><h2 id="videotutorial" tabindex="-1">Videotutorial <a class="header-anchor" href="#videotutorial" aria-label="Permalink to &quot;Videotutorial&quot;">​</a></h2>',47),e("iframe",{"data-extension":"youtube",width:"560",height:"315",src:"//www.youtube-nocookie.com/embed/Scrgk2y0w9s?",frameborder:"0",allowfullscreen:""},null,-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Sch%C3%BClercontainer_(Sch%C3%BCler)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),s(" · Quellrevision 5084.")],-1)])])}const z=r(c,[["render",o]]);export{k as __pageData,z as default};
